public class LedgerPostAnalysisControlProbe extends LedgerRegistrationControlProbe {
 public LedgerPostAnalysisControlProbe(Book b,SortedSet<Integer> ids){super(b,ids);}
 void privateCall(Object target,String name)throws Exception{Method m=target.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(target);}
 String population(Object p)throws Exception{int n=(Integer)call(p,"getCardinality");if(n==0)return "null";double mean=((Number)call(p,"getMeanValue")).doubleValue(),sd=((Number)call(p,"getStandardDeviation")).doubleValue();return "["+(mean-sd)+","+(mean+sd)+"]";}
 String statistics(Object p)throws Exception{return "{\"delta_above_range\":"+population(get(p,"popDeltaAbove"))+",\"delta_below_range\":"+population(get(p,"popDeltaBelow"))+",\"height_range\":"+population(get(p,"popHeight"))+",\"width_range\":"+population(get(p,"popWidth"))+"}";}
 String path(Object shape)throws Exception{PathIterator it=((java.awt.Shape)shape).getPathIterator(null);List<String> seg=new ArrayList<>();double[]previous=null;while(!it.isDone()){double[]v=new double[6];int type=it.currentSegment(v);if(type==0)previous=new double[]{v[0],v[1]};else{List<String> points=new ArrayList<>();points.add(Arrays.toString(previous));int count=type==1?1:type==2?2:3;for(int n=0;n<count;n++)points.add(Arrays.toString(new double[]{v[2*n],v[2*n+1]}));previous=new double[]{v[2*count-2],v[2*count-1]};seg.add("["+String.join(",",points)+"]");}it.next();}return "["+String.join(",",seg)+"]";}
 public void process(){try{
  sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet");for(String step:new String[]{"sheet.grid.GridStep","sheet.header.HeadersStep","sheet.stem.StemSeedsStep","sheet.beam.BeamsStep"})call(make(step),"doit",sheet);Class<?> o=Class.forName("org.audiveris.omr.run.Orientation");vertical=o.getField("VERTICAL").get(null);horizontal=o.getField("HORIZONTAL").get(null);Map<?,?> sections=(Map<?,?>)call(make("sheet.ledger.LedgersFilter",sheet),"process");Object context=make("sheet.ledger.LedgersStep$Context",sections);Map<Object,Object> builders=(Map)get(context,"builders");Map<Object,List<?>> candidates=new LinkedHashMap<>();Map<Object,Integer> local=new HashMap<>();
  for(Object sys:(List<?>)call(sheet,"getSystems")){system=sys;Object b=make("sheet.ledger.LedgersBuilder",sys);builders.put(sys,b);call(b,"buildLedgers",sections.get(sys));candidates.put(sys,new ArrayList<>((List<?>)get(b,"ledgerCandidates")));List<Object> nodes=new ArrayList<>(((Map<?,?>)get(b,"stick2ledger")).values());nodes.sort(Comparator.comparingInt(n->{try{return (Integer)call(n,"getId");}catch(Exception e){throw new RuntimeException(e);}}));for(int n=0;n<nodes.size();n++)local.put(nodes.get(n),n+1);}
  Object inspect=make("sheet.ledger.LedgersPostAnalysis",sheet,context);privateCall(inspect,"collect");privateCall(inspect,"filter");String stats=statistics(inspect);List<String> infos=new ArrayList<>(),discard=new ArrayList<>();for(Object info:((Map<?,?>)get(inspect,"infoMap")).values()){Object ledger=get(info,"ledger"),staff=get(info,"staff");infos.add("{\"system_id\":"+call(call(staff,"getSystem"),"getId")+",\"ledger_id\":"+local.get(ledger)+",\"staff_id\":"+call(staff,"getId")+",\"key\":"+get(info,"key")+",\"interline\":"+call(staff,"getSpecificInterline")+",\"delta\":"+get(info,"delta")+",\"height\":"+get(info,"height")+",\"width\":"+get(info,"width")+"}");}for(var entry:((Map<?,?>)get(inspect,"discarded")).entrySet())for(Object n:(List<?>)entry.getValue())discard.add("["+call(entry.getKey(),"getId")+","+local.get(n)+"]");
  call(make("sheet.ledger.LedgersPostAnalysis",sheet,context),"process");List<String> systems=new ArrayList<>();for(Object sys:(List<?>)call(sheet,"getSystems")){Object builder=builders.get(sys);List<String> nodes=new ArrayList<>(),maps=new ArrayList<>(),paths=new ArrayList<>();Map<?,?> cache=(Map<?,?>)get(builder,"stick2ledger");for(Object stick:candidates.get(sys)){Object n=cache.get(stick);if(n!=null){Object staff=call(n,"getStaff");nodes.add("{\"id\":"+local.get(n)+",\"candidate_index\":"+(candidates.get(sys).indexOf(stick)+1)+",\"index\":"+call(n,"getIndex")+",\"staff_id\":"+(staff==null?"null":call(staff,"getId"))+",\"bounds\":"+rect(call(n,"getBounds"))+",\"grade\":"+call(n,"getGrade")+",\"removed\":"+call(n,"isRemoved")+"}");}}
   for(Object staff:(List<?>)call(sys,"getStaves")){List<String> lines=new ArrayList<>(),lp=new ArrayList<>();for(var e:((Map<?,?>)call(staff,"getLedgerMap")).entrySet()){List<String>ids=new ArrayList<>();for(Object n:(List<?>)e.getValue())ids.add(local.get(n).toString());lines.add("{\"index\":"+e.getKey()+",\"ledger_ids\":["+String.join(",",ids)+"]}");}for(var e:((Map<?,?>)get(staff,"ledgerLineMap")).entrySet())lp.add("{\"index\":"+e.getKey()+",\"segments\":"+path(e.getValue())+"}");maps.add("{\"staff_id\":"+call(staff,"getId")+",\"lines\":["+String.join(",",lines)+"]}");paths.add("{\"staff_id\":"+call(staff,"getId")+",\"ledger_paths\":["+String.join(",",lp)+"]}");}systems.add("{\"system_id\":"+call(sys,"getId")+",\"inters\":["+String.join(",",nodes)+"],\"staff_maps\":["+String.join(",",maps)+"],\"ledger_paths\":["+String.join(",",paths)+"]}");}
  List<String> controls=new ArrayList<>();Object staff=((List<?>)call(system,"getStaves")).get(0);for(int il:new int[]{(Integer)call(staff,"getSpecificInterline")})for(int sign:new int[]{-1,1})for(double outlier:new double[]{0,0.99,1,2,3,4}){Object a=make("sheet.ledger.LedgersPostAnalysis",sheet,context);List<String> ci=new ArrayList<>();for(int n=0;n<5;n++){double d=n==4?il+outlier:il,h=n==4?1+outlier:1,w=22;Object l=make("sig.inter.LedgerInter",new Line2D.Double(200,200,222,200),h,Double.valueOf(.8));call(l,"setId",n+1);call(l,"setStaff",staff);Object info=make("sheet.ledger.LedgersPostAnalysis$Info",l,staff,sign,d,d/il,h,h/il,w,w/il);((Map)get(a,"infoMap")).put(l,info);call(get(a,sign<0?"popDeltaAbove":"popDeltaBelow"),"includeValue",d/il);call(get(a,"popHeight"),"includeValue",h/il);call(get(a,"popWidth"),"includeValue",w/il);ci.add("{\"system_id\":"+call(system,"getId")+",\"ledger_id\":"+(n+1)+",\"staff_id\":"+call(staff,"getId")+",\"key\":"+sign+",\"interline\":"+il+",\"delta\":"+d+",\"height\":"+h+",\"width\":"+w+"}");}privateCall(a,"filter");List<String>ds=new ArrayList<>();for(var e:((Map<?,?>)get(a,"discarded")).entrySet())for(Object n:(List<?>)e.getValue())ds.add("["+call(e.getKey(),"getId")+","+call(n,"getId")+"]");controls.add("{\"infos\":["+String.join(",",ci)+"],\"statistics\":"+statistics(a)+",\"discarded\":["+String.join(",",ds)+"]}");}
  Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"native_outputs_used\":false,\"infos\":["+String.join(",",infos)+"],\"statistics\":"+stats+",\"discarded\":["+String.join(",",discard)+"],\"systems\":["+String.join(",",systems)+"],\"controls\":["+String.join(",",controls)+"],\"scope\":\"Fresh original in-memory GRID through BEAMS then unmodified ledger builder/post-analysis/rebuild/translated staff ledger paths; 12 direct statistical filter controls.\"}\n");
 }catch(Exception e){throw new RuntimeException(e);}}
}
